refentry.refsect1:
&reftitle.description;
voidstream_bucket_prepend resourcebrigade StreamBucketbucket
This function can be called to prepend a bucket to a bucket brigade. It is typically called from php_user_filter::filter.

  &reftitle.examples;

   stream_bucket_prepend example


<?php

class header_filter extends php_user_filter
{
    private bool $headerSent = false;

    public function filter($in, $out, &$consumed, bool $closing): int
    {
        while ($bucket = stream_bucket_make_writeable($in)) {
            $consumed += $bucket->datalen;
            stream_bucket_append($out, $bucket);

            if (!$this->headerSent) {
                $this->headerSent = true;
                // The header bucket is placed before the buckets already in $out
                stream_bucket_prepend($out, stream_bucket_new($this->stream, "Header\n"));
            }
        }

        return PSFS_PASS_ON;
    }
}

stream_filter_register('header', 'header_filter');

$fp = fopen('php://memory', 'w+');
stream_filter_append($fp, 'header', STREAM_FILTER_WRITE);
fwrite($fp, "Body\n");
rewind($fp);

echo stream_get_contents($fp);


   &example.outputs;


Header
Body
